/* HoneyBee Trace Oracle - seed demo data doanh nghiep.
   Data dung ASCII de tranh loi ma hoa khi chay SQLPlus/Windows.
   Moc thoi gian demo xoay quanh 2026-06-03.
*/
SET DEFINE OFF;






/* 10 agricultural batches with realistic dates and different business states. */








/* Scan data: product 1 safe, product 2 has 41 scans today => WARNING, product 8/9/10 demonstrate DANGER conditions. */
BEGIN
  FOR i IN 1..10 LOOP
    VALUES ('HB-QR-VEG-001-SAFE', 1, '127.0.0.'||i, 'Seed Browser', 'SUCCESS', 'NONE', 'Safe scan demo.', CURRENT_TIMESTAMP - NUMTODSINTERVAL(i, 'MINUTE'));
  END LOOP;
  FOR i IN 1..41 LOOP
    VALUES ('HB-QR-MANGO-002-WARN40', 2, '10.0.0.'||i, 'Seed Browser', 'SUCCESS', CASE WHEN i <= 40 THEN 'NONE' ELSE 'MEDIUM' END, 'Seed scans for >40 warning demo.', CURRENT_TIMESTAMP - NUMTODSINTERVAL(i, 'MINUTE'));
  END LOOP;
END;
/



COMMIT;
